// OpenRaff v1 — Factory contract.
//
// Deploys immutable Raffle instances at deterministic addresses and stamps the
// protocol parameters (fee, draw_timeout, treasury) into each instance. See
// docs/versions/v1/messages.md §4.

import "../gen/Raffle.code"
import "common"
import "messages"

contract RaffleFactory {
    author: "OpenRaff"
    version: "0.1.0"
    description: "OpenRaff factory: deploys immutable raffle instances"
    storage: FactoryStorage
    incomingMessages: FactoryMessage
}

type FactoryMessage =
    | CreateRaffle
    | SetParams

fun onInternalMessage(in: InMessage) {
    val msg = lazy FactoryMessage.fromSlice(in.body);

    match (msg) {
        CreateRaffle => handleCreateRaffle(in.valueCoins, msg),
        SetParams => handleSetParams(in.senderAddress, msg),
        else => {
            assert (in.body.isEmpty()) throw Errors.InvalidMessage;
        }
    }
}

fun onBouncedMessage(_in: InMessageBounced) {}

fun handleCreateRaffle(msgValue: coins, msg: CreateRaffle) {
    var fs = FactoryStorage.load();
    val config = msg.config.load();

    // Validate the organizer-provided configuration.
    assert (config.softCap > 0 && config.softCap <= config.hardCap) throw Errors.InvalidConfig;
    assert (config.ticketPrice > 0) throw Errors.InvalidConfig;
    assert (
        blockchain.now() <= config.saleStart && config.saleStart < config.saleDeadline
    ) throw Errors.InvalidConfig;
    val prizeCount = countPrizes(config.prizes);
    assert (prizeCount > 0) throw Errors.InvalidConfig;

    val raffleId = fs.raffleCount;

    // Force-add the organizer's ed25519 key as the fallback publisher.
    var publishers = msg.publishers;
    publishers.set(msg.organizerPubkey, 1);

    val meta: RaffleMeta = {
        raffleId,
        factory: contract.getAddress(),
        protocolFeeBps: fs.protocolFeeBps,
        drawTimeout: fs.drawTimeout,
        treasury: fs.treasury,
        config: msg.config,
        publishers,
        prizeCount: prizeCount as uint32,
    };

    val runtime: RaffleRuntime = {
        totalCollected: 0,
        ticketsSold: 0,
        salesClosedAt: 0,
        targetRound: 0,
        randomness: 0,
        drandSignature: null,
        drawCounter: 0,
        winnersDrawn: 0,
        jettonWallet: null,
    };

    val maps: RaffleMaps = {
        ledgerByIndex: [],
        participants: [],
        winners: [],
        drawSwap: [],
    };

    val initStorage: RaffleStorage = {
        status: STATUS_SCHEDULED,
        meta: meta.toCell(),
        runtime: runtime.toCell(),
        maps: maps.toCell(),
    };

    // Forward the incoming value (minus a small factory-side buffer) to fund
    // the new instance's storage.
    assert (msgValue > GAS_RESERVE) throw Errors.InsufficientValue;
    val stateInit: ContractState = { code: raffleCompiledCode(), data: initStorage.toCell() };
    val instanceAddr = (AutoDeployAddress { stateInit }).calculateAddress();
    val deployMsg = createMessage({
        bounce: BounceMode.NoBounce,
        value: msgValue - GAS_RESERVE,
        dest: { stateInit },
    });
    deployMsg.send(SEND_MODE_REGULAR);

    fs.raffleCount = raffleId + 1;
    fs.save();

    emitEvent(EvRaffleCreated {
        raffleId,
        instance: instanceAddr,
        organizer: config.organizer,
        paymentJetton: config.paymentJetton,
    });
}

fun handleSetParams(senderAddress: address, msg: SetParams) {
    var fs = FactoryStorage.load();
    assert (senderAddress == fs.owner) throw Errors.NotOwner;

    fs.protocolFeeBps = msg.protocolFeeBps;
    fs.drawTimeout = msg.drawTimeout;
    fs.treasury = msg.treasury;
    fs.save();
}

// --------------------------------------------------------------------------
// Get methods
// --------------------------------------------------------------------------

// (protocol_fee_bps, draw_timeout, treasury, raffle_count, owner)
get fun factoryData(): (int, int, address, int, address) {
    val fs = FactoryStorage.load();
    return (fs.protocolFeeBps, fs.drawTimeout, fs.treasury, fs.raffleCount, fs.owner);
}

// SPDX-License-Identifier: MIT
// Auto-generated dependency code for contract 'Raffle'
// Provides compiled BoC data for the 'Raffle' contract
//
// This file is automatically generated by 'acton build'
// Do not edit manually — changes will be overwritten

/// Returns `Raffle`'s code as a cell.
///
/// - Contract: `Raffle`
/// - Path: `contracts/Raffle.tolk`
///
/// # Safety
///
/// This function always returns the correct cell with the contract code.
@pure
fun raffleCompiledCode(): cell asm """
    "" base64>B B>boc PUSHREF
"""

// OpenRaff v1 — shared types, storage layout, errors and helpers.
//
// See docs/versions/v1/{specification,messages}.md for the design of record.
// v1 implements the native-TON payment path; the jetton path is the next
// increment and is intentionally left out here (storage/handlers are shaped so
// it can be added without reshuffling the core).

// ---------------------------------------------------------------------------
// Lifecycle status (stored as uint8). See specification §6.
// ---------------------------------------------------------------------------
const STATUS_SCHEDULED = 0
const STATUS_ACTIVE = 1
const STATUS_SALES_CLOSED = 2
const STATUS_DRAWING = 3
const STATUS_DRAWN = 4
const STATUS_COMPLETED = 5
const STATUS_REFUNDING = 6
// Terminal-settlement retry state: the protocol fee has been paid to the
// treasury, but the organizer payout bounced and is awaiting a `Settle` retry.
// See Raffle.onBouncedMessage.
const STATUS_SETTLING = 7

// Max winners a single `draw` call resolves before yielding; the draw resumes
// across further calls via `drawCounter`. Sampling is without replacement (see
// Raffle.handleDraw), so each call does exactly this many sha256 samples — gas
// per transaction is bounded regardless of K vs N. Calibrated in
// tests/gas.test.tolk: a full batch of 48 winners costs ~444k gas — comfortably
// under the 1,000,000 basechain limit. A draw call should attach ~1 TON to
// cover gas plus up to 48 winner-event actions.
const DRAW_BATCH = 48

// Small ton buffer the raffle keeps for storage rent / outgoing gas.
const GAS_RESERVE = 20000000 // 0.02 TON

// TON attached to a single TEP-74 jetton `transfer` to fund the two-hop wallet
// chain; the unused remainder returns to the recipient via `excesses`. Paid out
// of the value of the message that triggered the transfer (buy/refund/settle).
const JETTON_SEND_GAS = 50000000 // 0.05 TON

// TON for the TEP-89 provide/take wallet-discovery handshake.
const WALLET_DISCOVERY_GAS = 30000000 // 0.03 TON

// ---------------------------------------------------------------------------
// Error / exit codes. See messages.md §7.
// ---------------------------------------------------------------------------
enum Errors {
    WrongStatus = 0x101
    NotOrganizer = 0x102
    SaleNotOpen = 0x103
    SaleEnded = 0x104
    SoldOut = 0x105
    InsufficientValue = 0x106
    UnauthorizedPublisher = 0x107
    WrongRound = 0x108
    BadSignature = 0x109
    DrawTimeout = 0x10A
    NothingToRefund = 0x10B
    NotJettonWallet = 0x10C
    InvalidConfig = 0x10D
    NotOwner = 0x10E
    InvalidMessage = 0xFFFF
}

// ---------------------------------------------------------------------------
// Domain types.
// ---------------------------------------------------------------------------

// A prize is off-chain metadata (an obligation of the organizer), never an
// on-chain asset. `title` and `metadata` are refs (URI + hash / inline).
struct Prize {
    title: cell
    metadata: cell
}

// DRAND network parameters. `publicKey` (BLS) is stored for off-chain / future
// on-chain verification; the contract itself does not verify BLS in v1.
struct Beacon {
    chainHash: uint256
    genesisTime: uint32
    period: uint32
    publicKey: cell
}

// Immutable, organizer-provided configuration of a raffle.
struct RaffleConfig {
    organizer: address
    ticketPrice: coins
    softCap: coins
    hardCap: coins
    saleStart: uint32
    saleDeadline: uint32
    metadata: cell
    beacon: Cell<Beacon>
    prizes: map<uint32, Prize>
    // Payment asset: null => native TON; set => the jetton master this raffle is
    // priced in (one asset per raffle; participants swap in the UI if needed).
    paymentJetton: address?
}

// Ledger entry: a single purchase covering tickets [startIndex .. startIndex+count).
struct LedgerEntry {
    count: uint32
    buyer: address
}

// Per-participant aggregate, keyed by sha256(address) — for refunds.
struct Participant {
    tickets: uint32
    contributed: coins
    refundClaimed: bool
}

// A resolved winner: prize `rank` goes to the owner of `ticketIndex`.
struct Winner {
    ticketIndex: uint32
    owner: address
}

// ---------------------------------------------------------------------------
// Raffle storage (root cell = status + 3 refs). See messages.md §5.1.
// ---------------------------------------------------------------------------

// Immutable bundle. `protocolFeeBps`/`drawTimeout`/`treasury` are protocol
// parameters stamped by the factory; the organizer does not set them.
struct RaffleMeta {
    raffleId: uint64
    factory: address
    protocolFeeBps: uint16
    drawTimeout: uint32
    treasury: address
    config: Cell<RaffleConfig>
    // ed25519 publisher allowlist; the organizer's key is added by the factory.
    publishers: map<uint256, uint8>
    // Number of prizes K, counted by the factory once at creation.
    prizeCount: uint32
}

// Mutable scalar state.
struct RaffleRuntime {
    totalCollected: coins
    ticketsSold: uint32
    salesClosedAt: uint32
    targetRound: uint64
    randomness: uint256
    drandSignature: cell?
    drawCounter: uint64 // draw sample cursor, persists across draw batches
    winnersDrawn: uint32
    // The raffle's own jetton wallet for `config.paymentJetton`, discovered
    // post-deploy via TEP-89. Null until discovered / in native mode.
    jettonWallet: address?
}

// The four dictionaries, grouped so the root stays within 4 refs.
struct RaffleMaps {
    ledgerByIndex: map<uint32, LedgerEntry> // startIndex -> (count, buyer)
    participants: map<uint256, Participant> // sha256(addr) -> aggregate
    winners: map<uint32, Winner>            // rank -> winner
    // Sparse Fisher-Yates state for sampling winners WITHOUT replacement:
    // position -> ticket index that currently lives there. Absent key => identity
    // (position p holds ticket p). See Raffle.handleDraw and specification §7.5.
    drawSwap: map<uint32, uint32>
}

struct RaffleStorage {
    status: uint8
    meta: Cell<RaffleMeta>
    runtime: Cell<RaffleRuntime>
    maps: Cell<RaffleMaps>
}

fun RaffleStorage.load(): RaffleStorage {
    return RaffleStorage.fromCell(contract.getData());
}

fun RaffleStorage.save(self) {
    contract.setData(self.toCell());
}

// ---------------------------------------------------------------------------
// Factory storage. See messages.md §4.1.
// ---------------------------------------------------------------------------
struct FactoryStorage {
    owner: address         // v1: protocol admin; future: DAO address
    protocolFeeBps: uint16 // v1: 30 (0.3%)
    drawTimeout: uint32    // v1: 259200 (72h)
    treasury: address
    raffleCount: uint64    // source of raffle_id
}

fun FactoryStorage.load(): FactoryStorage {
    return FactoryStorage.fromCell(contract.getData());
}

fun FactoryStorage.save(self) {
    contract.setData(self.toCell());
}

// ---------------------------------------------------------------------------
// Fairness helpers. See specification §7.5.
// ---------------------------------------------------------------------------

// Deterministic draw index for a given counter, uniform in [0, n):
//   idx = sha256(randomness ‖ le64(counter)) mod n
// In handleDraw `n` is the shrinking pool size `remaining` (sampling without
// replacement), so this yields the position to pick, never a rejected sample.
fun computeDrawIndex(randomness: uint256, counter: uint64, n: int): int {
    val h = beginCell()
        .storeUint(randomness, 256)
        .storeUint(counter, 64)
        .endCell()
        .beginParse()
        .bitsHash();
    return h % n;
}

// Authorization preimage signed by a publisher (ed25519):
//   auth = (raffleId ‖ targetRound ‖ randomness)
// The signer signs sha256(auth); CHKSIGNS verifies against that.
fun buildAuthSlice(raffleId: uint64, targetRound: uint64, randomness: uint256): slice {
    return beginCell()
        .storeUint(raffleId, 64)
        .storeUint(targetRound, 64)
        .storeUint(randomness, 256)
        .endCell()
        .beginParse();
}

// Counts prize entries in the config (K). Done once by the factory at creation.
fun countPrizes(prizes: map<uint32, Prize>): int {
    var cnt = 0;
    var e = prizes.findFirst();
    while (e.isFound) {
        cnt += 1;
        e = prizes.iterateNext(e);
    }
    return cnt;
}

// DRAND target round fixed at sales close. See specification §7.2.
//   round_at(t)  = floor((t - genesis) / period) + 1
//   target_round = round_at(t) + 1   (first round strictly after t)
fun computeTargetRound(closedAt: int, genesisTime: int, period: int): int {
    val roundAt = (closedAt - genesisTime) / period + 1;
    return roundAt + 1;
}

// An empty TEP-74 `forward_payload` (Either Cell ^Cell): a single 0 bit selects
// the inline variant with no data. Used when we forward jettons without a note.
fun emptyForwardPayload(): slice {
    return beginCell().storeUint(0, 1).endCell().beginParse();
}

// Emits an opcode-tagged event as an external-out log message (dest = addr_none):
// no value, cannot change state, visible to indexers/UI. IGNORE_ERRORS so a
// failed log action never reverts the real state transition. See messages.md §5.10.
fun emitEvent<T>(body: T) {
    val ev = createExternalLogMessage({ dest: createAddressNone(), body });
    ev.send(SEND_MODE_IGNORE_ERRORS);
}

// OpenRaff v1 — incoming message bodies (opcodes). See messages.md §2.
//
// Note on the organizer publisher key: on-chain the organizer is identified by
// a TON address (receives funds, may cancel), but a *publisher* is an ed25519
// key. These are distinct, so `CreateRaffle` carries the organizer's ed25519
// pubkey explicitly and the factory force-adds it to the allowlist (the
// always-available fallback publisher of specification §7.3).

import "common"

// ------------------------------- Factory -----------------------------------

struct (0xF0000001) CreateRaffle {
    queryId: uint64
    organizerPubkey: uint256        // ed25519; force-added to publishers
    config: Cell<RaffleConfig>
    publishers: map<uint256, uint8> // extra auto-publisher keys (may be empty)
}

// Admin stopgap until DAO governance. Affects future raffles only.
struct (0xF0000002) SetParams {
    queryId: uint64
    protocolFeeBps: uint16
    drawTimeout: uint32
    treasury: address
}

// -------------------------------- Raffle -----------------------------------

struct (0xA0000001) BuyTicket {
    queryId: uint64
    count: uint32
}

struct (0xA0000002) CloseSales {
    queryId: uint64
}

struct (0xA0000003) SubmitRandomness {
    queryId: uint64
    round: uint64
    randomness: uint256
    signature: cell          // DRAND BLS signature (stored, not verified in v1)
    publisherPubkey: uint256 // ed25519
    edSignature: cell        // ed25519 signature (512 bits) over the auth preimage
}

struct (0xA0000007) DrawStep {
    queryId: uint64
}

struct (0xA0000004) Settle {
    queryId: uint64
}

struct (0xA0000005) Cancel {
    queryId: uint64
}

struct (0xA0000006) ClaimRefund {
    queryId: uint64
}

// Permissionless trigger for the one-off TEP-89 wallet discovery of a jetton
// raffle (the UI calls it once after creation). No-op / rejected in native mode.
struct (0xA0000008) SetupJettonWallet {
    queryId: uint64
}

// --------------------------- Jetton standard -------------------------------
// TEP-74 (jettons) + TEP-89 (wallet discovery). `forward_payload` and the
// optional trailing `owner_address` are consumed as an opaque remainder.

// Incoming: our jetton wallet notifies us that `amount` jettons arrived from
// `sender` (the buyer). This is the jetton-path equivalent of BuyTicket.
struct (0x7362D09C) JettonTransferNotification {
    queryId: uint64
    amount: coins
    sender: address
    forwardPayload: RemainingBitsAndRefs
}

// Outgoing: instruct our jetton wallet to send `amount` jettons to `destination`
// (payout / refund / excess). `responseDestination` receives the TON excesses.
struct (0x0F8A7EA5) JettonTransfer {
    queryId: uint64
    amount: coins
    destination: address
    responseDestination: address
    customPayload: cell?
    forwardTonAmount: coins
    forwardPayload: RemainingBitsAndRefs
}

// Outgoing: ask the jetton master for our wallet address (TEP-89).
struct (0x2C76B973) ProvideWalletAddress {
    queryId: uint64
    ownerAddress: address
    includeAddress: bool
}

// Incoming: the jetton master's reply carrying our wallet address (TEP-89).
struct (0xD1735400) TakeWalletAddress {
    queryId: uint64
    walletAddress: address
    rest: RemainingBitsAndRefs
}

// ------------------------- Events (external-out) ---------------------------
// Emitted as external-out log messages (dest = addr_none) at each significant
// transition, so an indexer / UI can reconstruct state without reading storage.
// They carry no value and cannot change state. Opcodes in the 0xE0.. range.

// Factory event: a new raffle instance was deployed.
struct (0xE0000001) EvRaffleCreated {
    raffleId: uint64
    instance: address
    organizer: address
    paymentJetton: address?
}

// Raffle events.
struct (0xE0000010) EvTicketPurchased {
    buyer: address
    count: uint32
    ticketsSold: uint32
    totalCollected: coins
}

struct (0xE0000011) EvSalesClosed {
    salesClosedAt: uint32
    targetRound: uint64
    ticketsSold: uint32
    totalCollected: coins
}

struct (0xE0000012) EvRandomnessPublished {
    round: uint64
    randomness: uint256
}

struct (0xE0000013) EvWinnerResolved {
    rank: uint32
    ticketIndex: uint32
    owner: address
}

// Emitted at the end of every draw batch; the draw is complete when
// winnersDrawn == target.
struct (0xE0000014) EvDrawProgress {
    winnersDrawn: uint32
    target: uint32
}

struct (0xE0000015) EvSettled {
    fee: coins
    payout: coins
}

struct (0xE0000016) EvCancelled {
    queryId: uint64
}

struct (0xE0000017) EvRefunded {
    buyer: address
    amount: coins
}

// Jetton wallet discovery completed (TEP-89).
struct (0xE0000018) EvWalletDiscovered {
    jettonWallet: address
}

// A bounceable payout/refund bounced back and was recovered (settle downgraded
// to retry, or the participant's refund flag was cleared). See
// Raffle.onBouncedMessage.
struct (0xE0000019) EvPayoutBounced {
    recipient: address
}
